grid.expression:
SELECT SUB.*, SUB.VLRPROD + SUB.VLRIPI + SUB.VLRSUBST + SUB.VLRFRETE + SUB.VLROUTROS AS VLRCONTABIL FROM ( SELECT UFSPAR.UF , PRO.CODPROD , PRO.REFFORN AS REFERENCIA , PAR.CODPARC AS CODPARC , PAR.RAZAOSOCIAL AS RAZSOCIAL , PAR.CGC_CPF AS CNPJ_PARCEIRO , PER.DESCRTIPPARC AS PERFIL , CAB.NUMNOTA AS NUMNF , CAB.DTNEG AS DTEMISSAO , CAB.DTENTSAI , PRO.DESCRPROD AS DESCRICAO , PRO.CODGRUPOPROD AS GRUPO , GRU.DESCRGRUPOPROD AS GRUPODESCRICAO , PRO.NCM , ITE.CODCFO AS CFOP , PRO.MARCA AS MARCA , ITE.QTDNEG AS QTDCOM , ITE.VLRUNIT , ITE.VLRTOT AS VLRPROD , ITE.BASEICMS AS BCICMS , ITE.ALIQICMS , ITE.VLRICMS , (SELECT D1.VALOR FROM TGFDIN D1 WHERE D1.CODIMP = 1 AND D1.NUNOTA = ITE.NUNOTA AND SEQUENCIA = ITE.SEQUENCIA AND D1.CODINC = 3) AS VLRICMS_FRETE , ITE.VLRIPI , ITE.VLRSUBST , ITE.BASESUBSTIT , ITE.CONTROLE AS CONTROLE --VLR FRETE TEM QUE SER RATEADO , (CASE WHEN ITE.VLRTOT = 0 OR CAB.VLRFRETE = 0 THEN 0 ELSE ITE.VLRTOT / (SELECT SUM( ITE.VLRTOT ) FROM TGFITE ITE WHERE ITE.NUNOTA = CAB.NUNOTA AND ITE.SEQUENCIA > 0) END)*CAB.VLRFRETE AS VLRFRETE , TPO.CODTIPOPER , TPO.DESCROPER , ITE.VLRDESC , (SELECT O1.OPCAO FROM TDDOPC O1 WHERE O1.NUCAMPO = 765 AND O1.VALOR = CAB.CIF_FOB) AS TIPOFRETE , (CASE WHEN ITE.VLRTOT = 0 OR CAB.VLROUTROS = 0 THEN 0 ELSE ITE.VLRTOT / (SELECT SUM( ITE.VLRTOT ) FROM TGFITE ITE WHERE ITE.NUNOTA = CAB.NUNOTA AND ITE.SEQUENCIA > 0 ) END)*CAB.VLROUTROS AS VLROUTROS , (SELECT O1.OPCAO FROM TDDOPC O1 WHERE O1.NUCAMPO = 856 AND O1.VALOR = CAB.TIPMOV) AS TIPMOV , ITE.VLRREPRED AS VLRREPRED , (SELECT SUM(D1.VLRDIFALDEST) FROM TGFDIN D1 WHERE D1.NUNOTA = CAB.NUNOTA AND D1.SEQUENCIA = ITE.SEQUENCIA) AS VLRDIFALDEST , (SELECT SUM(D1.VLRDIFALREM) FROM TGFDIN D1 WHERE D1.NUNOTA = CAB.NUNOTA AND D1.SEQUENCIA = ITE.SEQUENCIA) AS VLRDIFALREM , CAB.AD_PACIENTE AS PACIENTE , CAB.AD_NOMMEDICO AS MEDICO , CAB.AD_DTCIRURG AS DT_CIRURGIA , CAB.AD_CLIENTEUSO AS COD_CLI_USO , USO.RAZAOSOCIAL AS RAZ_CLI_USO , USO.CGC_CPF AS CNPJ_PARC_USO , TRA.RAZAOSOCIAL AS TRANSPORTADORA , CAB.AD_CONVENIO AS CONVENIO , CAB.AD_PEDCLIENTE AS ORDEM_COMPRA , CAB.AD_NUMAFP AS NUM_AFP , CAB.AD_NUMEROCONTRATOCLIENTE AS CONTRATO_CLIENTE , CIDPAR.NOMECID AS CIDADE , TPV.DESCRTIPVENDA AS DESC_TP_PRAZO , GRUPOPIS AS PIS , GRUPOCOFINS AS COFINS
FROM TGFCAB CAB INNER JOIN TGFPAR PAR ON CAB.CODPARC = PAR.CODPARC INNER JOIN TSICID CIDPAR ON PAR.CODCID = CIDPAR.CODCID INNER JOIN TSIUFS UFSPAR ON UFSPAR.CODUF = CIDPAR.UF LEFT JOIN TGFTPP PER ON PER.CODTIPPARC = PAR.CODTIPPARC LEFT JOIN TGFTPV TPV ON TPV.CODTIPVENDA = CAB.CODTIPVENDA AND CAB.DHTIPVENDA = TPV.DHALTER INNER JOIN TGFITE ITE ON CAB.NUNOTA = ITE.NUNOTA INNER JOIN TGFPRO PRO ON ITE.CODPROD = PRO.CODPROD INNER JOIN TGFTOP TPO ON CAB.CODTIPOPER = TPO.CODTIPOPER AND CAB.DHTIPOPER = TPO.DHALTER INNER JOIN TGFGRU GRU ON PRO.CODGRUPOPROD = GRU.CODGRUPOPROD LEFT JOIN TGFPAR USO ON CAB.AD_CLIENTEUSO = USO.CODPARC LEFT JOIN TGFPAR TRA ON CAB.CODPARCTRANSP = TRA.CODPARC
WHERE TPO.ATUALLIVFIS <> 'N' AND CAB.CODEMP = :CODEMP AND CAB.DTNEG BETWEEN :DTENTSAI.INI AND :DTENTSAI.FIN AND CAB.STATUSNOTA = 'L' AND (CAB.CODPARC = :P_CODPARC OR :P_CODPARC IS NULL) AND (PRO.CODPROD = :P_CODPROD OR :P_CODPROD IS NULL) AND (PRO.CODMARCA= :P_CODMARCA OR :P_CODMARCA IS NULL) AND TPO.ATUALLIVFIS <> 'N' --Se emite NFE, tem que estar aprovada. AND ((TPO.NFE IN ('N','D') --AND CAB.STATUSNFE = 'A' ) OR TPO.NFE NOT IN ('N','D')) AND ((CAB.TIPMOV IN ('V', 'E') AND :TIPMOV = 'S') OR (CAB.TIPMOV IN ('C', 'D') AND :TIPMOV = 'E') OR (CAB.TIPMOV IN ('V','E','C', 'D') AND :TIPMOV = 'A') ) ) SUB ORDER BY SUB.DTENTSAI, SUB.NUMNF;
